import{_ as e,o,c as r,ag as a}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Tool Handout","description":"","frontmatter":{"source":"TOOLS.md"},"headers":[],"relativePath":"TOOLS.md","filePath":"TOOLS.md"}'),d={name:"TOOLS.md"};function s(n,t,i,l,h,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="tool-handout" tabindex="-1">Tool Handout <a class="header-anchor" href="#tool-handout" aria-label="Permalink to &quot;Tool Handout&quot;">​</a></h1><blockquote><p><strong>Last verified: 21 October 2026</strong>, including the &quot;as of&quot; dates in the table headers. Free tiers change monthly. Instructors re-check every tool the week before each cohort and again at mid-course, before week 9. Found something out of date? <a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/issues/new/choose" target="_blank" rel="noreferrer">Open a &quot;tool change&quot; issue</a>.</p></blockquote><p>This is the <strong>only</strong> file in the course that names model versions, credit amounts or prices. Everything else teaches ideas that outlast any product.</p><h2 id="the-stack-at-a-glance" tabindex="-1">The stack at a glance <a class="header-anchor" href="#the-stack-at-a-glance" aria-label="Permalink to &quot;The stack at a glance&quot;">​</a></h2><p>Every layer has a primary free tool and two fallbacks. When you run out of credits or a tool breaks, switch to the next one in the row. That is a planned drill, not an emergency.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Used in</th><th>Primary ($0)</th><th>Fallback 1</th><th>Fallback 2</th><th>Optional paid step</th></tr></thead><tbody><tr><td><strong>Chat assistant with live preview</strong></td><td>Weeks 1–6</td><td>Google Gemini (Canvas)</td><td>ChatGPT Free</td><td>Claude Free (Artifacts, 18+)</td><td>Not needed</td></tr><tr><td><strong>Browser app builder</strong></td><td>Week 6</td><td>Google AI Studio <em>Build</em> (18+)</td><td>Bolt Free</td><td>Lovable, v0 or Replit (one session each)</td><td>Only if a capstone outgrows free credits ($16–25/mo)</td></tr><tr><td><strong>Code editor + AI assistant</strong></td><td>Weeks 6–16</td><td>VS Code + GitHub Copilot Free/Student, in GitHub Codespaces</td><td>Google Antigravity (18+)</td><td>Cline or Kilo Code + a free LLM API or local Ollama</td><td>Copilot Pro ($10/mo)</td></tr><tr><td><strong>Terminal agent</strong></td><td>Weeks 11–16</td><td>GitHub Copilot CLI (in a Codespace)</td><td>Antigravity CLI (18+)</td><td>OpenCode + free models (Aider has had no release since Aug 2025)</td><td>Claude Code (Claude Pro, $20/mo) or Codex CLI (ChatGPT Plus, $20/mo) for weeks 11–16</td></tr><tr><td><strong>LLM API inside your app</strong></td><td>Weeks 9–16</td><td>Gemini API free tier, Flash-Lite model <code>gemini-3.5-flash-lite</code> (18+, not for apps serving EEA/UK/Swiss users)</td><td>Groq free plan</td><td>OpenRouter free models · Cloudflare Workers AI · local Ollama</td><td>Pay per token</td></tr><tr><td><strong>Hosting</strong></td><td>Weeks 2–16</td><td>GitHub Pages (static sites)</td><td>Vercel Hobby (personal repos; not private repos owned by an organization)</td><td>Cloudflare Workers</td><td>—</td></tr><tr><td><strong>Database and auth</strong></td><td>Weeks 13–16</td><td>Supabase Free</td><td>Neon or Turso (database only)</td><td>—</td><td>—</td></tr><tr><td><strong>Save everything</strong></td><td>Always</td><td>GitHub</td><td>—</td><td>—</td><td>—</td></tr></tbody></table><p><strong>Under 18, or in the EEA/UK?</strong> Tell your instructor before the course starts: the class switches to an adjusted stack.</p><h2 id="credits-budget-for-the-course" tabindex="-1">Credits budget for the course <a class="header-anchor" href="#credits-budget-for-the-course" aria-label="Permalink to &quot;Credits budget for the course&quot;">​</a></h2><p>The course runs for a 16-week semester, so your GitHub Copilot use stretches across several monthly allowances. Plan your credits across weeks 6–16 instead of hoping they last.</p><ul><li><strong>Credits reset on the first of each calendar month</strong>, not when the course starts. A 16-week semester covers parts of four or five months, and the agent weeks (11–16) cross at least one reset, so note which reset dates fall inside them.</li><li><strong>Weeks 1–5</strong> use chat assistants, not Copilot, and week 6 uses app builders and then a chat assistant to start Project 1. <strong>Weeks 6–10</strong> mostly use completions and Ask mode, which are light. <strong>Weeks 11–16</strong> use agent mode, which uses far more credits per request. Save most of each month&#39;s allowance for those weeks.</li><li><strong>Spend less per task:</strong> one task per chat, a fresh chat when a conversation gets long, small steps (the <a href="./resources/safe-loop.html">Safe Loop</a>), and Ask mode when you only need an explanation. Check the usage meter (the Copilot icon in the status bar) at the start of each week.</li><li><strong>When credits stop,</strong> chat and agent mode stop until the month resets. Copilot has no cheaper fallback model. Switch to the fallback in the stack table straight away: Antigravity (18+), or Cline or Kilo Code with a free Groq or OpenRouter key, in the editor; OpenCode with free models in the terminal. Tell your instructor, and see <a href="./resources/troubleshooting.html#i-ran-out-of-free-credits">troubleshooting</a>.</li><li><strong>Students:</strong> apply for GitHub Education early. Copilot Student adds unlimited completions and its own monthly credit allowance.</li></ul><h2 id="layer-details" tabindex="-1">Layer details <a class="header-anchor" href="#layer-details" aria-label="Permalink to &quot;Layer details&quot;">​</a></h2><h3 id="chat-assistants-weeks-16" tabindex="-1">Chat assistants (weeks 1–6) <a class="header-anchor" href="#chat-assistants-weeks-16" aria-label="Permalink to &quot;Chat assistants (weeks 1–6)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Free tier (as of 2026-10-21)</th><th>Cheapest paid</th><th>Coding features</th><th>Age</th><th>Training on your data by default?</th></tr></thead><tbody><tr><td><strong>Gemini</strong></td><td>Flash-Lite model by default since 9 Oct 2026 (the Auto setting may send some prompts to Flash or Pro); limits refresh every 5 hours up to a weekly cap; numbers not published</td><td>Google AI Plus $4.99 (adds Flash) · AI Pro $19.99 (adds Pro and Gemini 4 Argon)</td><td><strong>Canvas</strong> runs HTML/JS previews in the chat; Gems (custom assistants). Google hasn&#39;t said which model runs Canvas on the free plan</td><td>13+</td><td>Yes if &quot;Keep Activity&quot; is on; samples may be read by human reviewers</td></tr><tr><td><strong>ChatGPT</strong></td><td>Unlimited text chat on the small default model (reported to be GPT-6 Luna since 8 Oct 2026), with ads</td><td>Go $8 · Plus $20</td><td>In-chat code blocks; basic Codex access for quick tasks. The side-panel <em>canvas</em> was reportedly removed in May 2026. Since Oct 2026 &quot;Intelligent UI&quot; can show small interactive widgets (charts, forms, calculators), but it does not run your own code</td><td>13+ with parental consent</td><td>Yes, opt out under Data Controls</td></tr><tr><td><strong>Claude</strong></td><td>Mid-size and small models (Sonnet 5.5 since 28 Sep 2026); limits reset every 5 hours, numbers not published</td><td>Pro $20 ($17/mo annual) — includes Claude Code</td><td><strong>Artifacts</strong> run HTML/JS/React previews in the chat</td><td><strong>18+</strong></td><td>Yes (since Sept 2025), opt out in Privacy settings</td></tr></tbody></table><p><strong>Which tool leads week 1?</strong> Gemini&#39;s free plan now runs its smallest model by default, and a third party reports a 32K-token context window on the free tier, so long one-shot builds may fail sooner than before. Start a fresh chat for each build. For an adult cohort, Claude Artifacts may now give the stronger free preview; the instructor&#39;s pre-cohort smoke test decides which tool leads week 1. ChatGPT is still not a live-preview tool.</p><h3 id="browser-app-builders-week-6" tabindex="-1">Browser app builders (week 6) <a class="header-anchor" href="#browser-app-builders-week-6" aria-label="Permalink to &quot;Browser app builders (week 6)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>What you get free</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Google AI Studio — Build</strong></td><td>Full-stack React + Node apps with a database and auth, two-way GitHub sync, no card to prototype</td><td>18+. Free-tier inputs may be used for training and read by human reviewers (except in the EEA, UK and Switzerland). Deploying to Cloud Run needs a billing account — we export to GitHub instead</td></tr><tr><td><strong>Bolt</strong></td><td>About 1M tokens/month (300K/day), hosting, private projects</td><td>Good fallback</td></tr><tr><td><strong>Lovable</strong></td><td>5 credits/day, capped at 30/month</td><td>Current chat pricing ends 31 Oct 2026; no replacement announced as of 21 Oct. Re-check in November</td></tr><tr><td><strong>v0</strong></td><td>New accounts: $5 of credits <strong>once</strong> (no monthly refill since Oct 2026); 7 messages/day</td><td>Older free accounts keep $5/month. Cheapest paid plan for new users is $30/mo</td></tr><tr><td><strong>Replit (Starter)</strong></td><td>Agent in &quot;Free Mode&quot; (replaced &quot;Lite&quot;) with daily credits up to a monthly cap; one published app that goes down after 30 days</td><td>Starter no longer appears on replit.com/pricing (since Sep 2026); check that a new sign-up still gets it. Keep your code in GitHub, not only in Replit</td></tr></tbody></table><p>v0 and Replit are one-session samplers at best.</p><h3 id="editor-and-agents-weeks-616" tabindex="-1">Editor and agents (weeks 6–16) <a class="header-anchor" href="#editor-and-agents-weeks-616" aria-label="Permalink to &quot;Editor and agents (weeks 6–16)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Free tier</th><th>Cheapest paid</th><th>Notes</th></tr></thead><tbody><tr><td><strong>GitHub Copilot Free</strong> (in VS Code / Codespaces)</td><td>2,000 completions/month; an unpublished monthly allowance of AI Credits; automatic model choice only; <strong>agent mode, MCP and Copilot CLI included</strong></td><td>Pro $10 (model choice, larger credit pool)</td><td>Since 1 June 2026, running out of credits <strong>stops</strong> chat/agent work until the month resets — there is no cheaper fallback model. Plan your credits (<a href="#credits-budget-for-the-course">budget</a>)</td></tr><tr><td><strong>GitHub Copilot Student</strong></td><td>Free for verified students: unlimited completions, a monthly AI Credits allowance (GitHub doesn&#39;t publish the number; third parties report 200), cloud agent, code review</td><td>—</td><td>Apply in week 0 or 1 through GitHub Education; verification can take days</td></tr><tr><td><strong>GitHub Codespaces</strong></td><td>120 core-hours/month on GitHub Free (about 60 hours on the default 2-core machine), 15 GB storage</td><td>—</td><td>Usage is <strong>blocked, not billed</strong>, when the quota runs out if you have no payment method. Stop your codespace when you finish</td></tr><tr><td><strong>Google Antigravity</strong> (IDE + <code>agy</code> CLI)</td><td>Gemini 3.8 Flash with a weekly limit (numbers not published). Claude 4.6 and gpt-oss-120b leave the free plan on 2 Nov 2026</td><td>Google AI Pro $19.99 (Gemini 4 Argon and Claude 5.5 need a paid plan that is not a trial)</td><td>18+. Still a good second opinion and fallback, but no longer a frontier-model tool on the free plan</td></tr><tr><td><strong>Claude Code</strong></td><td>Not free</td><td>Claude Pro $20</td><td>Excellent agent; optional for weeks 11–16. Reads the course&#39;s <code>AGENTS.md</code> when a project has no <code>CLAUDE.md</code> (from v2.1.277)</td></tr><tr><td><strong>OpenAI Codex CLI</strong></td><td>Basic access on Free (quick tasks only)</td><td>ChatGPT Plus $20</td><td>Optional for weeks 11–16. University students in the US and Canada can claim $100 of Codex credits that work with ChatGPT Free (<a href="#student-offers-check-eligibility">student offers</a>); not yet tested by the course</td></tr><tr><td><strong>OpenCode / Cline / Kilo Code</strong></td><td>Free, open source</td><td>Pay for the model you connect</td><td>Connect to Groq, OpenRouter free models or Ollama. OpenCode, Cline and Kilo Code all shipped releases in Oct 2026. OpenCode&#39;s repository moved to <code>anomalyco/opencode</code>. Keep your keys in your own environment variables, not in a hosted console: OpenCode&#39;s hosted Console was breached in Oct 2026 (the open-source tool was not affected)</td></tr></tbody></table><h3 id="llm-apis-for-your-own-apps-weeks-916" tabindex="-1">LLM APIs for your own apps (weeks 9–16) <a class="header-anchor" href="#llm-apis-for-your-own-apps-weeks-916" aria-label="Permalink to &quot;LLM APIs for your own apps (weeks 9–16)&quot;">​</a></h3><p>All of these accept requests in the OpenAI &quot;chat completions&quot; format, so the starter code switches between them by changing three environment variables (<code>LLM_BASE_URL</code>, <code>LLM_API_KEY</code>, <code>LLM_MODEL</code>).</p><table tabindex="0"><thead><tr><th>Provider</th><th><code>LLM_BASE_URL</code></th><th>Free limits (as of 2026-10-21)</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Gemini API</strong> (key from Google AI Studio)</td><td><code>https://generativelanguage.googleapis.com/v1beta/openai/</code></td><td>Not published (see AI Studio). Earlier third-party reports: about 500/day on Flash-Lite and about 20/day on Flash (not re-confirmed in Oct 2026). Use <code>gemini-3.5-flash-lite</code>; <code>gemini-3.1-flash-lite</code> may shut down from 7 May 2027</td><td>18+. Free-tier data may be used for training and read by reviewers. Free tier may not serve users in the EEA, UK or Switzerland. AI Studio advertises Gemini 4 Argon, but it isn&#39;t on the free tier</td></tr><tr><td><strong>Groq</strong></td><td><code>https://api.groq.com/openai/v1</code></td><td>30 requests/minute, 1,000/day on open models such as gpt-oss</td><td>No card. Does not retain inference data by default</td></tr><tr><td><strong>OpenRouter</strong></td><td><code>https://openrouter.ai/api/v1</code></td><td>50 requests/day on <code>:free</code> models (more after a one-time $10 top-up)</td><td>Free-model providers may log prompts</td></tr><tr><td><strong>Cloudflare Workers AI</strong></td><td><code>https://api.cloudflare.com/client/v4/accounts/[ACCOUNT_ID]/ai/v1</code></td><td>10,000 &quot;Neurons&quot;/day</td><td>Needs a Cloudflare account ID. Some newer models need a paid plan</td></tr><tr><td><strong>Ollama (local)</strong></td><td><code>http://localhost:11434/v1</code></td><td>Unlimited, runs on your machine</td><td>Useful models need about 16 GB RAM; not available inside a Codespace without extra setup</td></tr></tbody></table><p>Model names change often. The suggested Gemini model ID is <code>gemini-3.5-flash-lite</code>. Run <code>npm run models</code> in the week 9 starter to list the exact model IDs your key can use.</p><h3 id="hosting-and-data" tabindex="-1">Hosting and data <a class="header-anchor" href="#hosting-and-data" aria-label="Permalink to &quot;Hosting and data&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Service</th><th>Free tier</th><th>Watch out for</th></tr></thead><tbody><tr><td><strong>GitHub Pages</strong></td><td>Static sites from public repos</td><td>Non-commercial; public repos only on free accounts</td></tr><tr><td><strong>Vercel Hobby</strong></td><td>Static sites + serverless functions from a personal repo</td><td>Non-commercial. <strong>Cannot deploy private repos owned by a GitHub organization</strong> (make the repo public or fork it to your personal account). 10 GB deployment storage (since 16 Sep 2026); each project keeps only its 3 latest production deployments plus its 3 latest of any kind, and older ones are deleted when you go over. Submit your <strong>production URL plus a screenshot</strong>, not a preview URL</td></tr><tr><td><strong>Cloudflare Workers</strong></td><td>Static assets + functions</td><td>Slightly more setup</td></tr><tr><td><strong>Supabase Free</strong></td><td>2 projects, Postgres database, auth</td><td><strong>Pauses after 1 week of inactivity</strong> — restore it from the dashboard. From 30 Oct 2026, new tables need explicit <code>grant</code>s before the API can see them; grant <strong>and</strong> turn on row-level security (RLS) with policies together. Use the publishable/secret keys; the legacy anon/service_role keys are deprecated by the end of 2026</td></tr><tr><td><strong>Neon / Turso</strong></td><td>Postgres (1 GB per project on Neon Free) / SQLite databases</td><td>Database only, no auth</td></tr></tbody></table><h2 id="student-offers-check-eligibility" tabindex="-1">Student offers (check eligibility) <a class="header-anchor" href="#student-offers-check-eligibility" aria-label="Permalink to &quot;Student offers (check eligibility)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Offer</th><th>Who</th><th>Deadline / terms</th></tr></thead><tbody><tr><td>GitHub Education → Copilot Student + Codespaces benefits</td><td>Verified students worldwide</td><td>Apply in week 0 or 1 (verification can take days)</td></tr><tr><td>Google AI Pro free for 12 months</td><td>US college students 18+ (AI Plus, which includes Flash but not Pro, in 140+ other markets)</td><td>Redeem by 31 Dec 2026, before any 2027 cohort begins. Needs a payment method and <strong>auto-renews</strong> — set a reminder to cancel</td></tr><tr><td>ChatGPT Plus free for 4 months</td><td>US college students</td><td>Claim by 31 Oct 2026; ended after that date. Set a reminder to cancel</td></tr><tr><td>Codex credits for students</td><td>Verified university students in the US and Canada</td><td>$100 of Codex credits (2,500 credits); works with ChatGPT Free; one per student; no card reported. <strong>Not yet tested by the course: instructors test it on an account before recommending it.</strong> One community report says the flagship Codex model is blocked on Free accounts</td></tr><tr><td>Azure for Students</td><td>Students</td><td>$100 credit, no card</td></tr></tbody></table><p>Offers that have <strong>ended</strong>: Cursor&#39;s free student year (closed 25 Jun 2026), Perplexity&#39;s free year.</p><h2 id="do-not-use-in-this-course" tabindex="-1">Do not use in this course <a class="header-anchor" href="#do-not-use-in-this-course" aria-label="Permalink to &quot;Do not use in this course&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Why</th></tr></thead><tbody><tr><td>GitHub Spark</td><td>Retired 31 Aug 2026</td></tr><tr><td>Firebase Studio</td><td>New sign-ups closed 22 Jun 2026; shuts down 22 Mar 2027</td></tr><tr><td>Gemini CLI with a free Google login</td><td>Free login access ended 18 Jun 2026 (an API key still works, with low limits)</td></tr><tr><td>GitHub Models</td><td>Retired 30 Jul 2026</td></tr><tr><td>Roo Code, Continue</td><td>Shut down / no longer maintained</td></tr><tr><td>Aider</td><td>No release since Aug 2025 and no commits since May 2026; treat it as unmaintained. Use OpenCode instead</td></tr><tr><td>Cursor</td><td>Since 12 Oct 2026 the free plan is part of the X/Grok &quot;X Subscription&quot; bundle, which includes social-network features; the $8 plan is Grok-only; no student offer</td></tr><tr><td>ChatGPT side-panel canvas</td><td>Reportedly removed May 2026</td></tr><tr><td>DeepSeek (as a required tool)</td><td>Stores data in China; banned on some government and school devices</td></tr><tr><td>Trae</td><td>Reported to keep sending usage data after telemetry was disabled</td></tr></tbody></table><h2 id="known-upcoming-changes" tabindex="-1">Known upcoming changes <a class="header-anchor" href="#known-upcoming-changes" aria-label="Permalink to &quot;Known upcoming changes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>30 Oct 2026</td><td>Supabase stops giving new tables automatic API grants in every project (existing tables keep theirs)</td></tr><tr><td>31 Oct 2026</td><td>Lovable&#39;s current pricing ends; ChatGPT Plus student offer closes</td></tr><tr><td>2 Nov 2026</td><td>Antigravity&#39;s Free and Plus plans lose Claude 4.6 and gpt-oss-120b, leaving Gemini 3.8 Flash</td></tr><tr><td>16 Nov 2026</td><td>Copilot deprecates several models on Pro and higher plans (Free and Student pick models automatically)</td></tr><tr><td>31 Dec 2026</td><td>Last day to redeem Google&#39;s AI Pro/Plus student offer</td></tr><tr><td>End of 2026</td><td>Supabase deprecates the legacy <code>anon</code> and <code>service_role</code> keys (use publishable and secret keys)</td></tr><tr><td>22 Mar 2027</td><td>Firebase Studio shuts down and deletes data</td></tr><tr><td>7 May 2027</td><td>Earliest shutdown of <code>gemini-3.1-flash-lite</code> (use <code>gemini-3.5-flash-lite</code>)</td></tr></tbody></table><p>Instructors: what to do on each date is in the pre-cohort checklist.</p><h2 id="privacy-settings-to-change-on-day-one" tabindex="-1">Privacy settings to change on day one <a class="header-anchor" href="#privacy-settings-to-change-on-day-one" aria-label="Permalink to &quot;Privacy settings to change on day one&quot;">​</a></h2><p>Step-by-step instructions: <a href="./setup/privacy-settings.html">Privacy settings</a>.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Setting</th></tr></thead><tbody><tr><td>ChatGPT</td><td>Settings → Data Controls → &quot;Improve the model for everyone&quot; → off</td></tr><tr><td>Claude</td><td>Settings → Privacy → &quot;Help improve Claude&quot; → off</td></tr><tr><td>Gemini</td><td>Gemini Apps Activity / &quot;Keep Activity&quot; → off (or use temporary chats)</td></tr><tr><td>GitHub Copilot</td><td>github.com → Settings → Copilot → Features (github.com/settings/copilot/features) → turn off use of your data for training</td></tr><tr><td>Google AI Studio / Gemini API</td><td>No opt-out on the free tier. Never paste personal or secret data</td></tr></tbody></table><p>Sources for every row: <a href="./research/landscape-report-2026-09.html">Teach the Loop, Not the Tool</a> and the notes in <a href="./research/">research/notes/</a>. October 2026 re-check: <a href="./research/landscape-update-2026-10.html">Free Tiers Shrink While Evidence Demands Friction</a> and <a href="./research/notes/2026-10/tool-changes-since-september.html">Tool changes since 25 September 2026: row-by-row verification of TOOLS.md (checked 21 October 2026)</a>.</p>',37)])])}const g=e(d,[["render",s]]);export{p as __pageData,g as default};
